{"word":"relegate","pos":"v","level":6,"meaning":"委托","example":"She likes to relegate difficult questions to her colleagues","definition":"refer to another person for decision or judgment","frequency":4,"synset":"02589013-v","alternate_meanings":["使降低地位","使降等","使降级","委托","驱逐"],"related_synsets":["00739662-v","02399331-v","02482425-v","02503803-v","02589013-v"],"id":224241883},
{"word":"subsidy","pos":"n","level":6,"meaning":"补贴","example":"a subsidy for research in artificial intelligence","definition":"a grant paid by a government to an enterprise that benefits the public","frequency":1,"synset":"13267014-n","alternate_meanings":["津贴","补助金","补贴"],"related_synsets":["13267014-n"],"id":85007727},
